import{_ as a,o,c as t,a8 as r}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.65 Electron 三层防线","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.65-electron-ipc-architecture.md","filePath":"comics/EP.65-electron-ipc-architecture.md","lastUpdated":1793706365000}'),l={name:"comics/EP.65-electron-ipc-architecture.md"};function i(n,e,c,d,s,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-65-electron-三层防线" tabindex="-1">EP.65 Electron 三层防线 <a class="header-anchor" href="#ep-65-electron-三层防线" aria-label="Permalink to &quot;EP.65 Electron 三层防线&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../91-electron-ipc-architecture">91-electron-ipc-architecture.md</a>（91.1 三层架构 / 91.2 IPC 通道 / 91.3 事件推送）· 示例：<code>examples/91-01-electron-ipc-architecture.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：渲染进程直接 require(&#39;fs&#39;)，XSS 即可操作系统——nodeIntegration 的灾难。</li><li><strong>第 2 格</strong>：码叔揭秘三层架构——main 掌权、preload 桥接、renderer 只用授权 API。</li><li><strong>第 3 格</strong>：像素酱实证 IPC 通道白名单与参数校验。</li><li><strong>第 4 格</strong>：码叔结案——主进程用 send 主动推送事件给渲染进程。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-nodeintegration-的风险" tabindex="-1">第 1 格 · nodeIntegration 的风险 <a class="header-anchor" href="#第-1-格-·-nodeintegration-的风险" aria-label="Permalink to &quot;第 1 格 · nodeIntegration 的风险&quot;">​</a></h3><ul><li>渲染进程开启 nodeIntegration 后能直接调 Node API；</li><li>一旦有 XSS 漏洞，黑客可操作系统（删文件、读密钥）；</li><li>现代 Electron 默认 <code>contextIsolation: true</code>，禁止直连。</li></ul><h3 id="第-2-格-·-三层架构" tabindex="-1">第 2 格 · 三层架构 <a class="header-anchor" href="#第-2-格-·-三层架构" aria-label="Permalink to &quot;第 2 格 · 三层架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>渲染进程(Chromium) ↔ preload(contextBridge) ↔ 主进程(Node)</span></span></code></pre></div><ul><li><strong>主进程</strong>：Node.js 环境，拥有系统能力（文件、网络、托盘）；</li><li><strong>preload</strong>：桥接层，用 <code>contextBridge.exposeInMainWorld</code> 暴露受控 API；</li><li><strong>渲染进程</strong>：纯网页环境，只能调 preload 暴露的方法。</li></ul><h3 id="第-3-格-·-ipc-权限校验" tabindex="-1">第 3 格 · IPC 权限校验 <a class="header-anchor" href="#第-3-格-·-ipc-权限校验" aria-label="Permalink to &quot;第 3 格 · IPC 权限校验&quot;">​</a></h3><ul><li>通道名白名单：只注册允许的通道；</li><li>参数校验：类型、范围（如禁止写 /sys 目录）；</li><li>最小权限：只暴露必要能力，不暴露整个 fs 模块。</li></ul><h3 id="第-4-格-·-主→渲染事件推送" tabindex="-1">第 4 格 · 主→渲染事件推送 <a class="header-anchor" href="#第-4-格-·-主→渲染事件推送" aria-label="Permalink to &quot;第 4 格 · 主→渲染事件推送&quot;">​</a></h3><ul><li><code>webContents.send(channel, data)</code>：主进程主动推送；</li><li><code>ipcRenderer.on(channel, cb)</code>：渲染进程监听；</li><li>与 <code>invoke</code>（渲染→主请求-响应）配合使用。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../91-electron-ipc-architecture#_91-7-本章避坑清单">《91.7 本章避坑清单》</a></p></blockquote><ol><li>开 nodeIntegration → XSS 等于系统沦陷；</li><li>preload 暴露整个 fs → 权限过大，应封装最小 API；</li><li>IPC 不校验参数 → 路径穿越漏洞。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>Electron 三层架构分别是什么？——<strong>主进程(Node) / preload(桥接) / 渲染进程(Chromium)</strong>。</li><li>为什么渲染进程不能直连 Node？——<strong>防止 XSS 漏洞被利用获取系统权限，必须通过 preload 暴露受控 API</strong>。</li><li>主进程如何主动推送消息给渲染进程？——<strong><code>webContents.send(channel, data)</code></strong>。</li></ol>',19)])])}const g=a(l,[["render",i]]);export{p as __pageData,g as default};
